<template><view :class="['app-page','rank-page',{dark}]"><ui-header title="消费排行榜" back/><view class="rank-hero"><view class="rank-badge"><ui-icon name="trophy" :size="42"/><text>消费总榜</text></view><view v-if="top.length" class="podium"><view v-if="top[1]" class="second"><view class="rank-avatar"><image v-if="top[1].avatar" class="avatar-image" :src="top[1].avatar" mode="aspectFill"/><ui-icon v-else name="user" :size="46"/></view><text>{{top[1].nickname}}</text><text>{{money(top[1].amount)}}</text><b>第二名</b></view><view v-if="top[0]" class="first"><view class="rank-avatar"><image v-if="top[0].avatar" class="avatar-image" :src="top[0].avatar" mode="aspectFill"/><ui-icon v-else name="user" :size="46"/></view><text>{{top[0].nickname}}</text><text>{{money(top[0].amount)}}</text><b>第一名</b></view><view v-if="top[2]" class="third"><view class="rank-avatar"><image v-if="top[2].avatar" class="avatar-image" :src="top[2].avatar" mode="aspectFill"/><ui-icon v-else name="user" :size="46"/></view><text>{{top[2].nickname}}</text><text>{{money(top[2].amount)}}</text><b>第三名</b></view></view></view><view v-if="list.length" class="rank-list"><text class="section-title">实时排行</text><text class="update">按已支付订单统计</text><view v-for="(item,index) in list" :key="item.id" class="rank-row"><text>{{formatRank(index+4)}}</text><view class="mini-avatar"><image v-if="item.avatar" class="avatar-image" :src="item.avatar" mode="aspectFill"/><ui-icon v-else name="user" :size="30" tone="muted"/></view><text>{{item.nickname}}</text><text>{{money(item.amount)}}</text></view></view><ui-page-status v-else :loading="loading" title="暂无排行数据" :description="error||'完成支付后会生成实时排行'" @retry="load"/></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';export default{data(){return{dark:false,loading:true,error:'',top:[],list:[]}},onLoad(){this.dark=isDark();this.load()},methods:{async load(){this.loading=true;try{const rows=await api.getRanking();this.top=rows.slice(0,3);this.list=rows.slice(3)}catch(e){this.error=e.message||'加载失败'}finally{this.loading=false}},money(v){return Number(v||0).toFixed(2)},formatRank(rank){return rank<10?'0'+rank:String(rank)}}}</script>
<style scoped>.rank-page{padding-bottom:40rpx}.rank-hero{height:610rpx;padding:42rpx 30rpx 0;background:radial-gradient(circle at 50% 0,#334d9a,#121c39 55%,#0b1122);color:#fff;text-align:center}.rank-badge{display:inline-flex;align-items:center;gap:10rpx;padding:10rpx 30rpx;border-radius:30rpx;background:linear-gradient(135deg,#fff3ce,#ffc95e);color:#1e1e1e;font-weight:800}.rank-tabs{display:flex;justify-content:space-around;margin:34rpx 0}.rank-tabs text{padding-bottom:10rpx}.rank-tabs .active{border-bottom:6rpx solid #fff}.podium{height:350rpx;display:flex;align-items:flex-end;justify-content:center}.podium>view{width:31%;padding:20rpx 5rpx;display:flex;flex-direction:column;align-items:center;gap:8rpx;border-radius:24rpx 24rpx 0 0;font-size:22rpx}.podium b{padding:5rpx 15rpx;border-radius:16rpx;background:rgba(70,68,132,.7)}.first{height:300rpx;background:linear-gradient(#ffe9b5,#ffc75f);color:#ad6500}.second{height:240rpx;background:linear-gradient(#e7f2ff,#b8d9ff);color:#4966a0}.third{height:215rpx;background:linear-gradient(#ffe7df,#ffbbae);color:#c35f59}.rank-avatar{width:84rpx;height:84rpx;margin-top:-58rpx;display:flex;align-items:center;justify-content:center;overflow:hidden;border:5rpx solid #fff;border-radius:50%;background:#f3f5f8}.avatar-image{width:100%;height:100%;border-radius:50%}.rank-list{margin-top:-1rpx;padding:30rpx;border-radius:28rpx 28rpx 0 0;background:var(--surface)}.update{margin-left:10rpx;color:var(--muted);font-size:21rpx}.rank-row{height:100rpx;display:grid;grid-template-columns:50rpx 60rpx 1fr 130rpx;align-items:center;gap:12rpx;border-bottom:1rpx solid var(--line)}.rank-row>text:last-child{text-align:right}.mini-avatar{width:56rpx;height:56rpx;overflow:hidden;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--surface-soft)}</style>
